def ev(key,kind,capture,locator,claim,url=None,at=None,cases=None):
 eid='b-'+key
 if eid in IDS: return eid
 x={'evidence_id':eid,'kind':kind,'capture':capture,'locator':locator,'supports_or_contradicts':claim,'url':url}
 if url:x['accessed_at']=at
 if cases:x['case_ids']=cases
 E.append(x);IDS[eid]=x;return eid
def source_rec(r):
 p=ART/r.get('path','absent'); data=p.read_bytes() if p.is_file() else b''
 u=r['url'];kind='primary_source'; why='Recipe ingredient table and preparation instructions.'
 text=data.decode('utf-8',errors='replace')
 if not r.get('sha256') or r.get('exit_code',0)!=0:kind='unsuccessful_search';why='Retrieval failed; no usable source bytes were obtained.'
 elif '/rest/compound/' in u and 'WrongCall' in text:kind='unsuccessful_search';why='Endpoint returns WrongCall, not compound evidence.'
 elif 'togomedium.org/medium/' in u:kind='unsuccessful_search';why='HTML application shell has no recipe content; not ingredient evidence.'
 elif 'Nothing found' in text:kind='unsuccessful_search';why='Current provider reports Nothing found; frozen recipe evidence remains version-bound.'
 elif 'mcc.nies.go.jp' in u:kind='unsuccessful_search';why='Legacy NIES URL redirects to collection home; no specific medium evidence.'
 elif 'laboratorynotes.com' in u:kind='unsuccessful_search';why='Secondary LB background cannot establish this BSM9 mixed-medium sulfate formula.'
 if kind=='unsuccessful_search':
  if data and r.get('sha256'):c=cap(r['path'])
  else:c=cap('b/captures/retrievals.json')
 else:c=cap(r['path'])
 eid=ev('source-'+sha(u.encode())[:16],kind,c,u+'; '+why,why,u,r['accessed_at'],[v for v in r.get('case_ids',[]) if v in {c['case_id'] for c in CS}] or None)
 U[u]=eid
 return eid,kind

